INSERT INTO `wp_posts` VALUES (3,1,'2026-07-29 07:20:14','2026-07-29 07:20:14','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost/wordpress.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-07-29 07:20:14','2026-07-29 07:20:14','',0,'http://localhost/wordpress/?page_id=3',0,'page','',0),(4,0,'2026-07-29 07:20:21','2026-07-29 07:20:21','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-07-29 07:20:21','2026-07-29 07:20:21','',0,'http://localhost/wordpress/2026/07/29/navigation/',0,'wp_navigation','',0),(5,0,'2026-07-29 07:20:21','2026-07-29 07:20:21','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-07-29 07:20:21','2026-07-29 07:20:21','',0,'http://localhost/wordpress/index.php/2026/07/29/navigation/',0,'wp_navigation','',0),(94,0,'2026-09-08 15:32:27','2026-09-08 15:32:27','','2026-09-08','','private','closed','closed','','2026-09-08','','','2026-09-08 15:32:27','2026-09-08 15:32:27','',0,'http://localhost/wordpress/?post_type=llar_digest_day&p=94',0,'llar_digest_day','',0),(93,0,'2026-09-08 15:32:27','2026-09-08 15:32:27','','2026-09-08','','private','closed','closed','','2026-09-08','','','2026-09-08 15:32:27','2026-09-08 15:32:27','',0,'http://localhost/wordpress/?post_type=llar_digest_day&p=93',0,'llar_digest_day','',0),(8,1,'2026-07-29 07:22:44','2026-07-29 07:22:44','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-twentytwentyfive','','','2026-07-29 07:22:44','2026-07-29 07:22:44','',0,'http://localhost/wordpress/index.php/2026/07/29/wp-global-styles-twentytwentyfive/',0,'wp_global_styles','',0),(95,1,'2026-09-08 15:36:20','0000-00-00 00:00:00','','Auto Draft','','auto-draft','open','open','','','','','2026-09-08 15:36:20','0000-00-00 00:00:00','',0,'http://localhost/wordpress/?p=95',0,'post','',0),(10,1,'2026-07-29 08:03:59','2026-07-29 08:03:59','\n<div class=\"hero-section\"><img class=\"pf-avatar\" src=\"http://localhost/wordpress/wp-content/uploads/2026/07/project-pic.jpeg\" alt=\"Jazzfer Inigo\">\n  <div class=\"tagline reveal reveal-delay-1\">Portfolio</div>\n  <h1 class=\"reveal reveal-delay-2\">Hi, I&#8217;m <span>Jazzfer Inigo</span></h1>\n  <p class=\"subtitle reveal reveal-delay-3\">4th Year I.T Student &amp; Web Developer</p>\n  <p class=\"desc reveal reveal-delay-3\">Passionate about crafting modern web experiences. Currently studying Information Technology and turning ideas into reality through clean, efficient code.</p>\n  <div class=\"hero-buttons reveal reveal-delay-4\">\n    <a href=\"/portfolio/\" class=\"btn-gradient primary\">View My Work <svg class=\"btn-arrow\" viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14m-7-7 7 7 7-7\"/></svg></a>\n    <a href=\"/contact/\" class=\"btn-gradient secondary\">Let&#8217;s Talk <svg class=\"btn-arrow\" viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 12h14m-7-7 7 7-7 7\"/></svg></a>\n    <a href=\"http://localhost/wordpress/wp-content/uploads/Jazzfer-Inigo-Resume.pdf\" class=\"btn-gradient outline\" download>Download Resume <svg class=\"btn-arrow\" viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14m-7-7 7 7 7-7\"/></svg></a>\n  </div>\n  <div class=\"hero-social reveal reveal-delay-4\">\n    <a href=\"https://github.com/Jazzfer-2003\" title=\"GitHub\">GH</a>\n    <a href=\"https://www.linkedin.com/in/jazzfer-inigo-ab4ab9413/\" title=\"LinkedIn\">LI</a>\n    <a href=\"https://web.facebook.com/jazzfer.quijano.inigo.2024\" title=\"Facebook\">FB</a>\n  </div>\n  <div class=\"pf-stats reveal reveal-delay-5\">\n    <div class=\"pf-stat\"><span class=\"pf-stat-num\">20</span><span class=\"pf-stat-label\">Certifications</span></div>\n    <div class=\"pf-stat\"><span class=\"pf-stat-num\">7+</span><span class=\"pf-stat-label\">Projects Built</span></div>\n    <div class=\"pf-stat\"><span class=\"pf-stat-num\">4th</span><span class=\"pf-stat-label\">Year IT Student</span></div>\n  </div>\n</div>\n','Home','','publish','closed','closed','','home','','','2026-07-31 15:01:42','2026-07-31 15:01:42','',0,'http://localhost/wordpress/index.php/home/',0,'page','',0),(11,1,'2026-07-29 08:04:09','2026-07-29 08:04:09','<!-- wp:html -->\n<div class=\"page-section\">\n  <h2 class=\"reveal\">About Me</h2>\n  <p class=\"reveal\" style=\"font-size:1.05rem;line-height:1.8;opacity:0.85\">I\'m a 4th year I.T Student passionate about web development and design. I specialize in building modern, responsive websites and applications that deliver great user experiences. I\'m constantly learning new technologies and improving my skills.</p>\n  <p class=\"reveal\" style=\"font-size:1.05rem;line-height:1.8;opacity:0.85;margin-top:16px\">Throughout my academic journey, I\'ve worked on various projects ranging from simple websites to complex web applications. I enjoy solving problems and turning ideas into reality through code. When I\'m not studying, I explore new tech trends and work on personal projects.</p>\n\n  <h2 class=\"reveal\" style=\"margin-top:60px\">My Skills</h2>\n  <div class=\"reveal\" style=\"margin-top:26px\"><a href=\"http://localhost/wordpress/wp-content/uploads/Jazzfer-Inigo-Resume.pdf\" class=\"btn-gradient primary\" download>Download My Resume <svg class=\"btn-arrow\" viewBox=\"0 0 24 24\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14m-7-7 7 7 7-7\"/></svg></a></div>\n  <div class=\"skills-grid reveal\">\n    <span class=\"skill-tag\">HTML5</span>\n    <span class=\"skill-tag\">CSS3</span>\n    <span class=\"skill-tag\">JavaScript</span>\n    <span class=\"skill-tag\">React</span>\n    <span class=\"skill-tag\">Node.js</span>\n    <span class=\"skill-tag\">WordPress</span>\n    <span class=\"skill-tag\">PHP</span>\n    <span class=\"skill-tag\">Python</span>\n    <span class=\"skill-tag\">Git</span>\n    <span class=\"skill-tag\">SQL</span>\n    <span class=\"skill-tag\">Responsive Design</span>\n    <span class=\"skill-tag\">UI/UX</span>\n  </div>\n\n  <h2 class=\"reveal\" style=\"margin-top:60px\">Education</h2>\n  <div class=\"timeline reveal\">\n    <div class=\"timeline-item\">\n      <h3>4th Year I.T Student</h3>\n      <div class=\"date\">2023 - 2026</div>\n      <p>Currently pursuing a Bachelor\'s degree in Information Technology. Focused on web development, database management, and software engineering.</p>\n    </div>\n  </div>\n\n\n  <h2 class=\"reveal\" style=\"margin-top:60px\">Experience &amp; Involvement</h2>\n  <div class=\"timeline reveal\">\n    <div class=\"timeline-item\">\n      <h3>Web Developer — Freelance &amp; Academic Projects</h3>\n      <div class=\"date\">2023 – Present</div>\n      <p>Designed and built web applications used by real people: my capstone enrollment system, deployed live on Render, the Quizard study platform, and interactive learning tools like a Periodic Table Explorer and a Polygon Shapes Visualizer.</p>\n    </div>\n    <div class=\"timeline-item\">\n      <h3>Cisco Networking Academy — Coursework</h3>\n      <div class=\"date\">2023 – 2025</div>\n      <p>Completed 11 self-paced Cisco NetAcad credentials spanning networking fundamentals, cybersecurity (Ethical Hacker, Network Defense, Cyber Threat Management), Python programming, and data science.</p>\n    </div>\n  </div>\n  <div class=\"stats-row reveal\">\n    <div class=\"stat-item\"><div class=\"stat-number\">20</div><div class=\"stat-label\">Certifications</div></div>\n    <div class=\"stat-item\"><div class=\"stat-number\">7+</div><div class=\"stat-label\">Projects Built</div></div>\n    <div class=\"stat-item\"><div class=\"stat-number\">3+</div><div class=\"stat-label\">Years Coding</div></div>\n  <h2 class=\"reveal\" style=\"margin-top:60px\">GitHub Activity</h2>\n  <p class=\"reveal\" style=\"opacity:0.75;margin-bottom:18px\">A live snapshot of my recent contributions:</p>\n  <div class=\"ghchart-wrap reveal\"><img src=\"https://ghchart.rshah.org/Jazzfer-2003\" alt=\"GitHub contribution graph for Jazzfer-2003\" loading=\"lazy\" onerror=\"this.parentElement.style.display=\'none\'\"></div>\n  </div>\n</div>\n<!-- /wp:html -->','About','','publish','closed','closed','','about','','','2026-09-09 00:25:24','2026-09-08 16:25:24','',0,'http://localhost/wordpress/index.php/about/',0,'page','',0),(12,1,'2026-07-29 08:04:09','2026-07-29 08:04:09','<!-- wp:html -->\n<div class=\"page-section-wide\">\n  <h2 class=\"reveal\">My Projects</h2>\n  <p class=\"section-sub reveal\">A collection of web applications and projects I\'ve built throughout my academic journey.</p>\n\n  <div class=\"card-grid\">\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/enrollment-system.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/enrollment-system.png\" alt=\"Palale Enrollment System\" loading=\"lazy\" decoding=\"async\" width=\"1920\" height=\"1080\"></picture></div>\n      <div class=\"card-body\">\n        <h3>Palale Enrollment System</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">Capstone</span><span class=\"card-tag\">PHP</span><span class=\"card-tag\">MySQL</span><span class=\"card-tag\">HTML</span><span class=\"card-tag\">CSS</span></div>\n        <p>A complete web-based enrollment system that handles student registration, subject management, and enrollment records with a secure admin dashboard.</p>\n        <div class=\"card-links\"><a href=\"http://localhost/wordpress/portfolio/palale-enrollment-system/\">Capstone Project</a><a href=\"https://palale-enrollment-system.onrender.com/\" target=\"_blank\" rel=\"noopener\" aria-label=\"View live site for Palale Enrollment System (opens in new tab)\">View Live Site</a></div>\n      </div>\n    </div>\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/quizard.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/quizard.png\" alt=\"Quizard - QuizForge App\" loading=\"lazy\" decoding=\"async\" width=\"1920\" height=\"1080\"></picture></div>\n      <div class=\"card-body\">\n        <h3>Quizard - QuizForge App</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">JavaScript</span><span class=\"card-tag\">HTML</span><span class=\"card-tag\">CSS</span><span class=\"card-tag\">GitHub Pages</span></div>\n        <p>An interactive quiz platform with dynamic question generation, score tracking, and responsive design - deployed on GitHub Pages.</p>\n        <div class=\"card-links\"><a href=\"http://localhost/wordpress/portfolio/quizard/\">Personal Project</a><a href=\"https://quizard-app.github.io/\" target=\"_blank\" rel=\"noopener\" aria-label=\"View live site for Quizard QuizForge App (opens in new tab)\">View Live Site</a></div>\n      </div>\n    </div>\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/home.webp?v=2\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/home.png?v=2\" alt=\"Google Sites Portfolio - Home\" loading=\"lazy\" decoding=\"async\" width=\"1280\" height=\"800\"></picture></div>\n      <div class=\"card-body\">\n        <h3>Google Sites Portfolio</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">Google Sites</span><span class=\"card-tag\">Portfolio</span></div>\n        <p>My alternative portfolio built on Google Sites - featuring my projects, skills, and achievements with a clean, accessible layout.</p>\n        <div class=\"card-links\"><a href=\"https://sites.google.com/view/jazzfer-inigo-portfolio/home\" target=\"_blank\" rel=\"noopener\" aria-label=\"View live site for Google Sites Portfolio (opens in new tab)\">View Live Site</a></div>\n      </div>\n    </div>\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/snake-ladder.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/snake-ladder.png\" alt=\"Snake and Ladder Game\" loading=\"lazy\" decoding=\"async\" width=\"1920\" height=\"1080\"></picture></div>\n      <div class=\"card-body\">\n        <h3>Snake and Ladder Game</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">JavaScript</span><span class=\"card-tag\">HTML</span><span class=\"card-tag\">CSS</span></div>\n        <p>A classic Snake and Ladder board game with interactive dice rolling, animated player movement, and multiplayer support.</p>\n        \n      </div>\n    </div>\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/polygon-shapes.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/polygon-shapes.png\" alt=\"Polygon Shapes Visualizer\" loading=\"lazy\" decoding=\"async\" width=\"1920\" height=\"1080\"></picture></div>\n      <div class=\"card-body\">\n        <h3>Polygon Shapes Visualizer</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">JavaScript</span><span class=\"card-tag\">Canvas</span><span class=\"card-tag\">Geometry</span></div>\n        <p>An interactive polygon shapes tool that displays and manipulates geometric shapes for educational purposes.</p>\n        \n      </div>\n    </div>\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/periodic-table.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/periodic-table.png\" alt=\"Periodic Table Explorer\" loading=\"lazy\" decoding=\"async\" width=\"1920\" height=\"1080\"></picture></div>\n      <div class=\"card-body\">\n        <h3>Periodic Table Explorer</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">HTML</span><span class=\"card-tag\">CSS</span><span class=\"card-tag\">JavaScript</span></div>\n        <p>An interactive periodic table of elements with detailed information, color-coded categories, and responsive layout.</p>\n        \n      </div>\n    </div>\n        <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/minalungao-go.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/minalungao-go.jpg\" alt=\"MinalungaoGO\" loading=\"lazy\" decoding=\"async\" width=\"1900\" height=\"905\"></picture></div>\n      <div class=\"card-body\">\n        <h3>MinalungaoGO</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">School Project</span><span class=\"card-tag\">Web App</span></div>\n        <p>A tourism website for Minalungao National Park in Nueva Ecija, built for school — showcasing emerald rivers, bamboo rafting, and rock formations with login and guest exploration features.</p>\n      </div>\n    </div>\n    <div class=\"card-item reveal\">\n      <div class=\"card-img\"><picture><source srcset=\"http://localhost/wordpress/wp-content/uploads/2026/09/booknook-library-system.webp\" type=\"image/webp\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/09/booknook-library-system.jpg\" alt=\"BookNook Library System\" loading=\"lazy\" decoding=\"async\" width=\"1920\" height=\"988\"></picture></div>\n      <div class=\"card-body\">\n        <h3>BookNook Library System</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">School Project</span><span class=\"card-tag\">Web App</span></div>\n        <p>A library management system built for school — track titles and available copies, log borrow and return transactions, browse book details, and manage everything through a secure admin area.</p>\n      </div>\n    </div>\n<div class=\"card-item reveal\">\n      <div class=\"card-img\" style=\"font-size:3.5rem\">&#x1F680;</div>\n      <div class=\"card-body\">\n        <h3>More Coming Soon</h3>\n        <div class=\"card-tags\"><span class=\"card-tag\">In Progress</span></div>\n        <p>I\'m currently working on new projects. Check back soon or follow me on GitHub to see what I\'m building!</p>\n        <div class=\"card-links\"><a href=\"https://github.com/Jazzfer-2003\" target=\"_blank\" rel=\"noopener\" aria-label=\"Follow Jazzfer Inigo on GitHub (opens in new tab)\">Follow on GitHub</a></div>\n      </div>\n    </div>\n  </div>\n</div>\n<!-- /wp:html -->','Portfolio','','publish','closed','closed','','portfolio','','','2026-09-09 00:35:36','2026-09-08 16:35:36','',0,'http://localhost/wordpress/index.php/portfolio/',0,'page','',0),(13,1,'2026-07-29 08:04:10','2026-07-29 08:04:10','\n<div class=\"page-section\">\n  <h2 class=\"reveal\">Get In Touch</h2>\n  <p class=\"section-sub reveal\">Have a project in mind or just want to connect? Feel free to reach out!</p>\n  <div class=\"contact-grid reveal\">\n    <div class=\"contact-info\">\n      <h3>Let&#8217;s Talk</h3>\n      <p>I&#8217;m always open to discussing new projects, creative ideas, or opportunities.</p>\n      <ul class=\"contact-methods\">\n        <li><span class=\"ci\">&#9993;</span> <a href=\"mailto:jazzferinigo@gmail.com\">jazzferinigo@gmail.com</a></li>\n        <li><span class=\"ci\">&#128222;</span> <a href=\"tel:+639487952853\">09487952853</a></li>\n        <li><span class=\"ci\">&#128205;</span> Philippines</li>\n        <li><span class=\"ci\">&#128025;</span> <a href=\"https://github.com/Jazzfer-2003\">GitHub</a></li>\n        <li><span class=\"ci\">&#128279;</span> <a href=\"https://www.linkedin.com/in/jazzfer-inigo-ab4ab9413/\">LinkedIn</a></li>\n        <li><span class=\"ci\">&#128216;</span> <a href=\"