:\'\';position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:radial-gradient(circle,rgba(37,99,235,0.1) 0%,transparent 60%);animation:pulse 8s ease-in-out infinite}\n@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.1)}}\n.hero-content{position:relative;z-index:1;max-width:700px}\n.hero .tagline{font-size:.9rem;color:#60a5fa;letter-spacing:.15em;text-transform:uppercase;margin-bottom:1rem}\n.hero h1{font-size:clamp(2.5rem,6vw,4.5rem);font-weight:800;line-height:1.1;margin-bottom:.5rem}\n.hero h1 span{background:linear-gradient(135deg,#60a5fa,#a78bfa);-webkit-background-clip:text;-webkit-text-fill-color:transparent}\n.hero .subtitle{font-size:clamp(1.1rem,2.5vw,1.5rem);color:#94a3b8;margin-bottom:1rem;font-weight:300}\n.hero .desc{color:#64748b;max-width:550px;margin:0 auto 2rem;font-size:1.05rem;line-height:1.7}\n.btn-group{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}\n.btn{display:inline-block;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:600;font-size:.95rem;transition:all .3s}\n.btn-primary{background:#2563eb;color:#fff}\n.btn-primary:hover{background:#1d4ed8;transform:translateY(-2px)}\n.btn-outline{border:2px solid rgba(255,255,255,0.2);color:#fff}\n.btn-outline:hover{border-color:#2563eb;background:rgba(37,99,235,0.1);transform:translateY(-2px)}\n.social-bar{display:flex;gap:16px;justify-content:center;margin-top:2.5rem}\n.social-bar a{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,0.08);color:#94a3b8;text-decoration:none;font-size:1.1rem;transition:all .3s}\n.social-bar a:hover{background:#2563eb;color:#fff;transform:translateY(-3px)}\n</style><div class=\"hero\"><div class=\"hero-content\"><div class=\"tagline\">Welcome to my portfolio</div><h1>Hi, I\'m <span>Jazzfer Inigo</span></h1><p class=\"subtitle\">Web Developer &amp; Designer</p><p class=\"desc\">I craft modern, responsive websites and digital experiences that bring ideas to life.</p><div class=\"btn-group\"><a href=\"http://localhost/wordpress/index.php/portfolio/\" class=\"btn btn-primary\">View My Work</a><a href=\"http://localhost/wordpress/index.php/contact/\" class=\"btn btn-outline\">Get In Touch</a></div><div class=\"social-bar\"><a href=\"#\" title=\"GitHub\">GH</a><a href=\"#\" title=\"LinkedIn\">LI</a><a href=\"#\" title=\"Twitter\">X</a><a href=\"#\" title=\"Email\">@</a></div></div></div><!-- /wp:html -->','Home','','inherit','closed','closed','','10-revision-v1','','','2026-07-30 01:26:08','2026-07-30 01:26:08','',10,'http://localhost/wordpress/?p=20',0,'revision','',0),(72,0,'2026-07-30 04:10:36','2026-07-30 04:10:36','<!-- wp:html -->\n<div class=\"page-section\">\n<div class=\"page-section-inner\">\n  <h2 class=\"section-title reveal\">About Me</h2>\n  <div class=\"about-grid\">\n    <div class=\"reveal\"><p>I\'m a 4th year I.T Student passionate about web development and design. I specialize in building modern, responsive websites and applications that deliver great user experiences. I\'m constantly learning new technologies and improving my skills.</p></div>\n    <div class=\"reveal\"><p>Throughout my academic journey, I\'ve worked on various projects ranging from simple websites to complex web applications. I enjoy solving problems and turning ideas into reality through code. When I\'m not studying, I explore new tech trends and work on personal projects.</p></div>\n  </div>\n\n  <h2 class=\"section-title reveal\" style=\"margin-top:70px\">My Skills</h2>\n  <div class=\"skills-grid reveal\">\n    <div class=\"skill-item\">HTML5</div><div class=\"skill-item\">CSS3</div><div class=\"skill-item\">JavaScript</div><div class=\"skill-item\">React</div><div class=\"skill-item\">Node.js</div><div class=\"skill-item\">WordPress</div><div class=\"skill-item\">PHP</div><div class=\"skill-item\">Python</div><div class=\"skill-item\">Git</div><div class=\"skill-item\">SQL</div><div class=\"skill-item\">Responsive Design</div><div class=\"skill-item\">UI/UX</div>\n  </div>\n\n  <h2 class=\"section-title reveal\" style=\"margin-top:70px\">Education</h2>\n  <div class=\"timeline reveal\">\n    <div class=\"timeline-item\"><h3>4th Year I.T Student</h3><div class=\"date\">2023 — 2026</div><p>Currently pursuing a Bachelor\'s degree in Information Technology. Focused on web development, database management, and software engineering.</p></div>\n  </div>\n\n  <div class=\"stat-grid reveal\">\n    <div class=\"stat-item\"><div class=\"stat-num\">4+</div><div class=\"stat-label\">Years Studying</div></div>\n    <div class=\"stat-item\"><div class=\"stat-num\">20+</div><div class=\"stat-label\">Projects Done</div></div>\n    <div class=\"stat-item\"><div class=\"stat-num\">100%</div><div class=\"stat-label\">Dedication</div></div>\n  </div>\n\n  <div class=\"btn-group reveal\" style=\"margin-top:40px\"><a href=\"#\" class=\"btn btn-outline\">Download Resume ↓</a></div>\n</div>\n</div>\n<!-- /wp:html -->','About','','inherit','closed','closed','','11-revision-v1','','','2026-07-30 04:10:36','2026-07-30 04:10:36','',11,'http://localhost/wordpress/?p=72',0,'revision','',0),(21,1,'2026-07-30 01:26:23','2026-07-30 01:26:23','<!-- wp:html --><style>\n.about-page{max-width:1000px;margin:0 auto;padding:20px}\n.timeline{position:relative;padding-left:30px;border-left:3px solid #2563eb;margin:30px 0}\n.timeline-item{margin-bottom:30px;position:relative}\n.timeline-item::before{content:\'\';position:absolute;left:-38px;top:5px;width:16px;height:16px;background:#2563eb;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px #2563eb}\n.timeline-item h3{margin:0 0 5px;color:#1e293b}\n.timeline-item .date{color:#64748b;font-size:.85rem;margin-bottom:5px}\n.timeline-item p{margin:0;color:#64748b;line-height:1.5}\n.skills-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:12px;margin:30px 0}\n.skill-item{background:#f1f5f9;border-radius:12px;padding:16px;text-align:center;font-weight:600;color:#1e293b;transition:all .3s;border:1px solid #e2e8f0}\n.skill-item:hover{background:#2563eb;color:#fff;transform:translateY(-3px);border-color:#2563eb}\n.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:20px;margin:30px 0;text-align:center}\n.stat{background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff;padding:30px 20px;border-radius:16px}\n.stat .num{font-size:2.5rem;font-weight:800;color:#60a5fa}\n.stat .label{font-size:.9rem;color:#94a3b8;margin-top:5px}\n</style>\n<div class=\"about-page\">\n  <h2 class=\"section-title\">About Me</h2>\n  <div class=\"about-grid\">\n    <div><p style=\"color:#475569;line-height:1.8;font-size:1.05rem\">I\'m a passionate web developer and designer based in the Philippines. With expertise in modern web technologies, I create responsive, user-friendly websites that deliver results. I believe in clean code, thoughtful design, and building digital experiences that make a difference.</p></div>\n    <div><p style=\"color:#475569;line-height:1.8;font-size:1.05rem\">When I\'m not coding, you\'ll find me exploring new technologies, contributing to open source projects, or working on creative side projects. I\'m always eager to learn and take on new challenges that push my skills further.</p></div>\n  </div>\n\n  <h2 class=\"section-title\" style=\"margin-top:60px\">My Skills</h2>\n  <div class=\"skills-grid\">\n    <div class=\"skill-item\">HTML5</div><div class=\"skill-item\">CSS3</div><div class=\"skill-item\">JavaScript</div><div class=\"skill-item\">React</div><div class=\"skill-item\">Node.js</div><div class=\"skill-item\">WordPress</div><div class=\"skill-item\">PHP</div><div class=\"skill-item\">Python</div><div class=\"skill-item\">Git</div><div class=\"skill-item\">SQL</div><div class=\"skill-item\">Responsive Design</div><div class=\"skill-item\">UI/UX</div>\n  </div>\n\n  <h2 class=\"section-title\" style=\"margin-top:60px\">Experience</h2>\n  <div class=\"timeline\">\n    <div class=\"timeline-item\"><h3>Senior Web Developer</h3><div class=\"date\">2023 - Present</div><p>Lead development team, architect solutions, and deliver high-quality web applications.</p></div>\n    <div class=\"timeline-item\"><h3>Junior Web Developer</h3><div class=\"date\">2020 - 2022</div><p>Built and maintained client websites, implemented responsive designs, and optimized performance.</p></div>\n    <div class=\"timeline-item\"><h3>Freelance Designer &amp; Developer</h3><div class=\"date\">2018 - 2020</div><p>Created websites and graphics for small businesses, developed brand identities.</p></div>\n  </div>\n\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"num\">10+</div><div class=\"label\">Years Experience</div></div>\n    <div class=\"stat\"><div class=\"num\">50+</div><div class=\"label\">Projects Done</div></div>\n    <div class=\"stat\"><div class=\"num\">30+</div><div class=\"label\">Happy Clients</div></div>\n    <div class=\"stat\"><div class=\"num\">100%</div><div class=\"label\">Dedication</div></div>\n  </div>\n</div><!-- /wp:html -->','About','','inherit','closed','closed','','11-revision-v1','','','2026-07-30 01:26:23','2026-07-30 01:26:23','',11,'http://localhost/wordpress/?p=21',0,'revision','',0),(31,1,'2026-07-30 01:46:06','2026-07-30 01:46:06','<!-- wp:html --><style>\n.portfolio-page{max-width:1100px;margin:0 auto;padding:60px 20px}\n.section-title{font-size:2rem;text-align:center;margin-bottom:3rem;position:relative;font-weight:700;color:#1e293b}\n.section-title::after{content:\'\';display:block;width:60px;height:4px;background:linear-gradient(135deg,#6366f1,#8b5cf6);margin:12px auto 0;border-radius:2px}\n.projects{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:24px}\n.project-card{background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.06);transition:all .3s;border:1px solid #e2e8f0}\n.project-card:hover{transform:translateY(-5px);box-shadow:0 12p