3>\n        <div class=\"project-tags\"><span class=\"tag\">Python</span><span class=\"tag\">Django</span><span class=\"tag\">API</span></div>\n        <p>A scheduling tool for social media posts with analytics and content calendar.</p>\n        <a href=\"#\" class=\"project-link\">View Project →</a></div>\n    </div>\n    <div class=\"project-card\">\n      <div class=\"project-img\">🏗️</div>\n      <div class=\"project-body\"><h3>Coming Soon</h3>\n        <p>Exciting new project in development. Stay tuned!</p></div>\n    </div>\n  </div>\n</div><!-- /wp:html -->','Portfolio','','inherit','closed','closed','','12-revision-v1','','','2026-07-30 01:58:10','2026-07-30 01:58:10','',12,'http://localhost/wordpress/?p=39',0,'revision','',0),(35,1,'2026-07-30 01:50:22','2026-07-30 01:50:22','<!-- wp:html --><style>\n.portfolio-page{max-width:1100px;margin:0 auto;padding:80px 20px}\n.section-title{font-size:2rem;text-align:center;margin-bottom:3rem;position:relative;font-weight:700;color:#f1f5f9}\n.section-title::after{content:\'\';display:block;width:50px;height:3px;background:linear-gradient(135deg,#4f46e5,#7c3aed);margin:12px auto 0;border-radius:2px}\n.projects{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:20px}\n.project-card{background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.06);border-radius:16px;overflow:hidden;transition:all .3s}\n.project-card:hover{transform:translateY(-4px);border-color:rgba(79,70,229,0.3);box-shadow:0 12px 40px rgba(0,0,0,0.4)}\n.project-img{height:160px;background:linear-gradient(135deg,#1e1b4b,#312e81);display:flex;align-items:center;justify-content:center;font-size:2.5rem;opacity:.9}\n.project-body{padding:22px}\n.project-body h3{margin:0 0 6px;color:#f1f5f9;font-size:1.1rem}\n.project-body p{color:#94a3b8;line-height:1.6;margin:0 0 14px;font-size:.9rem}\n.project-tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}\n.tag{background:rgba(79,70,229,0.1);color:#a78bfa;padding:3px 10px;bor