-wrap:wrap;gap:6px;margin-bottom:14px}\n.tag{background:#eff6ff;color:#2563eb;padding:4px 10px;border-radius:6px;font-size:.75rem;font-weight:500;border:1px solid #dbeafe}\n.project-links{display:flex;gap:12px}\n.project-link{display:inline-flex;align-items:center;gap:6px;color:#2563eb;text-decoration:none;font-weight:500;font-size:.85rem;transition:all .2s}\n.project-link:hover{gap:10px}\n.project-link.demo{color:#64748b}\n.project-link.demo:hover{color:#2563eb}\n</style>\n<div class=\"portfolio-page\">\n  <h2 class=\"section-title\">My Projects</h2>\n  <p class=\"section-sub\">A collection of web applications and projects I\'ve built throughout my academic journey.</p>\n\n  <h3 style=\"color:#0f172a;font-size:1.2rem;margin-bottom:20px\">💻 Web Development</h3>\n  <div class=\"projects\" style=\"margin-bottom:50px\">\n    <div class=\"project-card\">\n      <div class=\"project-img\" style=\"background:linear-gradient(135deg,#dbeafe,#ede9fe)\"><div class=\"overlay\"></div>🌐</div>\n      <div class=\"project-body\">\n        <h3>E-Commerce Platform</h3>\n        <div class=\"project-tags\"><span class=\"tag\">React</span><span class=\"tag\">Node.js</span><span class=\"tag\">MongoDB</span></div>\n        <p>A full-featured online store with product catalog, shopping cart, user authentication, and payment integration using Stripe.</p>\n        <div class=\"project-links\"><a href=\"#\" class=\"project-link\">Live Demo →</a><a href=\"#\" class=\"project-link demo\">GitHub</a></div>\n      </div>\n    </div>\n    <div class=\"project-card\">\n      <div class=\"project-img\" style=\"background:linear-gradient(135deg,#fce7f3,#ffe4e6)\"><div class=\"overlay\"></div>📱</div>\n      <div class=\"project-body\">\n        <h3>Task Manager App</h3>\n        <div class=\"project-tags\"><span class=\"tag\">React Native</span><span class=\"tag\">Firebase</span><span class=\"tag\">Redux</span></div>\n        <p>A cross-platform mobile app for managing daily tasks with real-time sync, push notifications, and team collaboration features.</p>\n        <div class=\"project-links\"><a href=\"#\" class=\"project-link\">Live Demo →</a><a href=\"#\" class=\"project-link demo\">GitHub</a></div>\n      </div>\n    </div>\n    <div class=\"project-card\">\n      <div class=\"project-img\" style=\"background:linear-gradient(135deg,#d1fae5,#ecfdf5)\"><div class=\"overlay\"></div>⚡</div>\n      <div class=\"project-body\">\n        <h3>Dashboard Analytics</h3>\n        <div class=\"project-tags\"><span class=\"tag\">React</span><span class=\"tag\">D3.js</span><span class=\"tag\">Python</span></div>\n        <p>An interactive analytics dashboard with real-time data visualization, custom reporting tools, and exportable charts.</p>\n        <div class=\"project-links\"><a href=\"#\" class=\"project-link\">Live Demo →</a><a href=\"#\" class=\"project-link demo\">GitHub</a></div>\n      </div>\n    </div>\n  </div>\n\n  <h3 style=\"color:#0f172a;font-size:1.2rem;margin-bottom:20px\">🎓 Academic Projects</h3>\n  <div class=\"projects\">\n    <div class=\"project-card\">\n      <div class=\"project-img\" style=\"background:linear-gradient(135deg,#fef3c7,#fffbeb)\"><div class=\"overlay\"></div>🎨</div>\n      <div class=\"project-body\">\n        <h3>Portfolio Website</h3>\n        <div class=\"project-tags\"><span class=\"tag\">WordPress</span><span class=\"tag\">CSS</span><span class=\"tag\">JavaScript</span></div>\n        <p>This portfolio site! A custom-designed responsive portfolio built on WordPress with modern UI/UX principles.</p>\n        <div class=\"project-links\"><a href=\"http://localhost/wordpress/\" class=\"project-link\" target=\"_blank\">Live Demo →</a><a href=\"#\" class=\"project-link demo\">GitHub</a></div>\n      </div>\n    </div>\n    <div class=\"project-card\">\n      <div class=\"project-img\" style=\"background:linear-gradient(135deg,#e0e7ff,#c7d2fe)\"><div class=\"overlay\"></div>📊</div>\n      <div class=\"project-body\">\n        <h3>Social Media Scheduler</h3>\n        <div class=\"project-tags\"><span class=\"tag\">Python</span><span class=\"tag\">Django</span><span class=\"tag\">API</span></div>\n        <p>A scheduling tool for social media posts with content calendar, analytics dashboard, and multi-platform API integration.</p>\n        <div class=\"project-links\"><a href=\"#\" class=\"project-link\">Live Demo →</a><a href=\"#\" class=\"project-link demo\">GitHub</a></div>\n      </div>\n    </div>\n    <div class=\"project-card\">\n      <div class=\"project-img\" style=\"background:linear-gradient(135deg,#e0e7ff,#f3e8ff)\"><div class=\"overlay\"></div>🏗️</div>\n      <div class=\"project-body\">\n        <h3>More Coming Soon</h3>\n        <div class=\"project-tags\"><span class=\"tag\">In Progress</span></div>\n        <p>I\'m currently working on new projects. Check back soon for updates, or follow me on GitHub to see what I\'m building!</p>\n        <div class=\"project-links\"><a href=\"https://github.com/Jazzfer-2003\" class=\"project-link\" target=\"_blank\">Follow on GitHub →</a></div>\n      </div>\n    </div>\n  </div>\n</div><!-- /wp:html -->','Portfolio','','inherit','closed','closed','','12-revision-v1','','','2026-07-30 02:00:07','2026-07-30 02:00:07','',12,'http://localhost/wordpress/?p=41',0,'revision','',0),(73,0,'2026-07-30 04:10:36','2026-07-30 04:10:36','<!-- wp:html -->\n<div class=\"page-section\">\n<div class=\"page-section-inner\">\n  <h2 class=\"section-title reveal\">My Projects</h2>\n  <p class=\"section-sub reveal\">A collection of web applications and projects I\'ve built throughout my academic journey.</p>\n\n  <h3 class=\"section-subheading reveal\">💻 Web Development</h3>\n  <div class=\"card-grid\" style=\"margin-bottom:50px\">\n    <div class=\"card reveal\">\n      <div class=\"card-img\" style=\"background:linear-gradient(135deg,#dbeafe,#ede9fe);font-size:3rem;color:#2563eb\">🛒</div>\n      <div class=\"card-body\">\n        <h3>E-Commerce Platform</h3>\n 